import { Alert, Button, Group, NumberInput, Progress, Stack, Text } from "@mantine/core";
import { useWidgetClock, useWidgetCommands, useWidgetHost, useWidgetOptions, useWidgetState } from "@homarr/widget-sdk";
export default function Timer() {
  const host = useWidgetHost();
  const options = useWidgetOptions<{title:string;minutes:number}>();
  const now = useWidgetClock(100);
  const [minutes, setMinutes] = useWidgetState("minutes", options.minutes);
  const [timer, setTimer] = useWidgetState<{remaining:number;deadline:number|null;duration:number}>("timer", { remaining: options.minutes * 60000, deadline: null, duration: options.minutes * 60000 });
  const remaining = timer.deadline === null || now === null ? timer.remaining : Math.max(0, timer.deadline - now);
  const running = timer.deadline !== null && remaining > 0;
  const start = () => setTimer({ remaining, duration: timer.duration, deadline: Date.now() + remaining });
  const pause = () => setTimer({ ...timer, remaining, deadline: null });
  const reset = () => setTimer({ remaining: minutes * 60000, duration: minutes * 60000, deadline: null });
  useWidgetCommands([{ id: "toggle", label: running ? "Pause timer" : "Start timer", disabled: remaining <= 0, run: running ? pause : start }, { id: "reset", label: "Reset timer", run: reset }]);
  const seconds = Math.ceil(remaining / 1000);
  return <Stack h="100%" justify="center" p="md" gap="sm">
    <Text c="dimmed" size="sm">{options.title}</Text>
    <Text ff="monospace" fw={700} fz={host.displayMode === "advanced" ? "4rem" : "2rem"} aria-live={remaining === 0 ? "polite" : "off"}>{Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, "0")}</Text>
    <Progress value={timer.duration ? 100 * (1 - remaining / timer.duration) : 0} aria-label="Elapsed timer duration" />
    {remaining === 0 && <Alert color="teal">Timer complete</Alert>}
    <Group><Button disabled={host.isEditMode || remaining <= 0} onClick={running ? pause : start}>{running ? "Pause" : "Start"}</Button><Button variant="light" disabled={host.isEditMode} onClick={reset}>Reset</Button></Group>
    {host.displayMode === "advanced" && <NumberInput label="Minutes for next reset" min={1} max={1440} value={minutes} onChange={(value) => { if (typeof value === "number") setMinutes(value); }} />}
  </Stack>;
}
